/* Build docs/cases/bundle.js from the per-brand case source files.

   Rationale (2026-09-01 架构评审候选 3): the app must work from file://,
   so cases cannot be fetched as JSON; but 30 hand-listed <script> tags in
   global-brand-building.html were the friction. The loader registry
   (docs/cases/loader.js CASES) is the single manifest — this script reads
   it and bundles each brand's work1..5 + index into one file loaded by a
   single tag. Edit the per-brand files, then:

       node scripts/build-cases-bundle.js

   The generated bundle is checked into the repo (file:// compatible).
   The bundle is a pure concatenation of the source IIFEs — each assigns
   its window.__case_* global exactly as before.
*/
'use strict';
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const casesDir = path.join(root, 'docs', 'cases');
const loaderSrc = fs.readFileSync(path.join(casesDir, 'loader.js'), 'utf8');

// Single manifest: brand keys in the loader's CASES registry, in order.
const brandRe = /^[ ]*'([a-z0-9-]+)': \{/gm;
const brands = [];
let m;
while((m = brandRe.exec(loaderSrc)) !== null) brands.push(m[1]);
if(!brands.length) throw new Error('No brands found in loader.js CASES registry');

const files = ['work1.js','work2.js','work3.js','work4.js','work5.js','index.js'];
const parts = [];
parts.push(`/* ============================================================
   Cases bundle — GENERATED by scripts/build-cases-bundle.js.
   Source: docs/cases/<brand>/{${files.join(',')}}.
   Regenerate after editing any case:  node scripts/build-cases-bundle.js
   Loaded by docs/global-brand-building.html with ONE <script> tag;
   docs/cases/loader.js remains the runtime registry and merge logic.
   ============================================================ */`);

for(const brand of brands){
  for(const f of files){
    const p = path.join(casesDir, brand, f);
    if(!fs.existsSync(p)) throw new Error('Missing case source: ' + path.relative(root, p));
    const src = fs.readFileSync(p, 'utf8').trim();
    parts.push(`/* ---- cases/${brand}/${f} ---- */`);
    parts.push(src);
  }
}

const out = parts.join('\n\n') + '\n';
const outPath = path.join(casesDir, 'bundle.js');
fs.writeFileSync(outPath, out, 'utf8');
console.log(`bundle written: docs/cases/bundle.js (${brands.join(', ')}) — ${out.length} chars`);
